#!/usr/bin/env node
/**
 * validate-pipeline.mjs — Orchestrator de Validação Completa
 *
 * Roda sequencialmente: lint → validate:design → test → test:a11y → build
 * Falha rápido: se qualquer step falhar, para e reporta.
 *
 * Uso:
 *   node node_modules/@dock-tech/shared-copilot-front-lib/scripts/validate-pipeline.mjs
 *   npm run validate
 *
 * Exit code 0 = pipeline inteira passou
 * Exit code 1 = algum step falhou
 */

import { execSync } from 'child_process';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';

const CWD = process.cwd();

// === Load Config ===

function loadConfig() {
  const configPath = join(CWD, 'dock-ds.config.json');
  if (existsSync(configPath)) {
    return JSON.parse(readFileSync(configPath, 'utf-8'));
  }
  return {};
}

function loadValidationScripts() {
  const config = loadConfig();
  return config.validation?.scripts || {};
}

// === Pipeline Steps ===

const configScripts = loadValidationScripts();
const fullConfig = loadConfig();

// Threshold mínimo de compliance score (0–100). Projetos abaixo bloqueiam build.
// Pode ser sobrescrito via dock-ds.config.json → validation.complianceThreshold
const COMPLIANCE_THRESHOLD = configScripts.complianceThreshold ?? fullConfig?.validation?.complianceThreshold ?? 85;

// Default pipeline order — override via dock-ds.config.json → validation.scripts
const STEPS = [
  { name: 'Lint', cmd: configScripts.lint || 'npm run lint --silent', optional: false },
  { name: 'Design Tokens', cmd: configScripts.design || 'npm run validate:design', optional: false },
  { name: 'Contrast WCAG', cmd: configScripts.contrast || 'npm run validate:contrast', optional: false },
  { name: 'Unit Tests', cmd: configScripts.unit || 'npm run test -- --run', optional: false },
  // A11y Tests: era optional=true (dívida técnica). Agora é bloqueante (P0 backlog).
  // Se ainda não há test:a11y configurado, o projeto DEVE adicionar para passar o pipeline.
  { name: 'A11y Tests', cmd: configScripts.a11y || 'npm run test:a11y -- --run', optional: false },
  { name: 'Compliance Score', cmd: configScripts.compliance || `npm run compliance -- --threshold ${COMPLIANCE_THRESHOLD}`, optional: false },
  { name: 'Build', cmd: 'npm run build', optional: false },
];

// === Execution ===

function runStep(step) {
  try {
    execSync(step.cmd, {
      cwd: CWD,
      stdio: 'pipe',
      encoding: 'utf-8',
      timeout: 120_000, // 2 min per step max
    });
    return { success: true };
  } catch (err) {
    return {
      success: false,
      output: (err.stdout || '') + '\n' + (err.stderr || ''),
      code: err.status,
    };
  }
}

function main() {
  console.log('═'.repeat(60));
  console.log('  🔄 Dock Validation Pipeline');
  console.log('═'.repeat(60));
  console.log(`  Projeto: ${CWD}`);
  console.log(`  Steps: ${STEPS.length}\n`);

  const results = [];
  let failed = false;

  for (const step of STEPS) {
    process.stdout.write(`  ⏳ ${step.name}...`);

    const result = runStep(step);

    if (result.success) {
      console.log(` ✅`);
      results.push({ ...step, status: 'passed' });
    } else if (step.optional) {
      console.log(` ⚠️  (opcional, pulando)`);
      results.push({ ...step, status: 'skipped' });
    } else {
      console.log(` ❌`);
      results.push({ ...step, status: 'failed', output: result.output });
      failed = true;
      break; // Fail fast
    }
  }

  // Summary
  console.log('\n' + '─'.repeat(60));
  console.log('  Resumo:');
  for (const r of results) {
    const icon = r.status === 'passed' ? '✅' : r.status === 'skipped' ? '⚠️' : '❌';
    console.log(`    ${icon} ${r.name} — ${r.status}`);
  }
  console.log('─'.repeat(60));

  if (failed) {
    const failedStep = results.find((r) => r.status === 'failed');
    console.log(`\n❌ Pipeline falhou em: ${failedStep.name}`);
    if (failedStep.output) {
      console.log('\n  Output:');
      const lines = failedStep.output.trim().split('\n').slice(-20);
      lines.forEach((l) => console.log(`    ${l}`));
    }
    console.log('\n  Corrija o problema e rode novamente: npm run validate\n');
    process.exit(1);
  }

  console.log('\n✅ Pipeline completa — pronto para PR!\n');
  process.exit(0);
}

main();
